import { ResourceAllocationChart, ResourceAllocationData } from '../types';
import { hasPublicisChartEntry } from './hasPublicisChartEntry';

const hasRankingDatasets = (chart: ResourceAllocationData): boolean =>
  Array.isArray(chart.datasets) &&
  chart.datasets.some(
    (dataset) => Array.isArray(dataset.data) && dataset.data.length > 0,
  );

export const hasOverviewRankingData = (
  rankingData?: ResourceAllocationChart,
): boolean => {
  if (!rankingData || typeof rankingData !== 'object') {
    return false;
  }

  return Object.values(rankingData).some((entry) => {
    const chart = entry as ResourceAllocationData;

    if (!chart || chart.empty) {
      return false;
    }

    return (
      hasRankingDatasets(chart) ||
      hasPublicisChartEntry(chart.overview_graph as ResourceAllocationData)
    );
  });
};
